const envelope = $json.body && typeof $json.body === 'object' ? $json.body : $json;
const value = envelope.entry?.[0]?.changes?.[0]?.value || {};
const message = Array.isArray(value.messages) ? value.messages[0] : null;
if (!message || !message.id) throw new Error('Message WhatsApp entrant absent ou sans identifiant.');
const contact = Array.isArray(value.contacts) ? value.contacts[0] : null;
const text = message.text?.body || message.button?.text || message.interactive?.button_reply?.title || message.interactive?.list_reply?.title || message.image?.caption || message.document?.caption || '';
const phone = String(message.from || contact?.wa_id || '').replace(/\D/g, '');
const content = String(text || '[Message non textuel]');
const referenceSource = String(envelope.reference_mission || envelope.reference || '') + '\n' + content;
const referenceMatch = referenceSource.match(/\bMIS-2026-\d{4}\b/i);
const optionBRequested = /\boption\s*b\b|\barbitrage\s+terrain\b|\bexpert\s+terrain\b|\bMIS-2026-/i.test(content);
const routingContext = { numero_whatsapp: phone, reference_mission: referenceMatch ? referenceMatch[0].toUpperCase() : '', option_b_requested: optionBRequested, message_id_parent: String(message.context?.id || ''), type_message: String(message.type || 'unknown') };
return { json: { numero_whatsapp: phone, message_id: String(message.id), reference_mission: routingContext.reference_mission, type_message: routingContext.type_message, contenu: content, date_reception_utc: new Date(Number(message.timestamp) * 1000 || Date.now()).toISOString(), routing_context: routingContext } };
